995	// MeasureStartSnapshot - F14 observer that captures (mcycle, minstret)
996	// K vsim-retires after entry. Used by the gem5-style warmup window: the
997	// vsim phase still runs N cold-cache cycles, but the reported ROI delta is
998	// taken from the K-th commit instead of from vsim entry, so the cold prefix
999	// is excluded from the measurement.
1000	//
1001	// Duck-types the observer surface the HandoffController invokes via
1002	// if-constexpr: `observe_commit() -> void`. Accessors expose the captured
1003	// values for F16 (StateDrain) to copy into the ABI struct.
1004	//
1005	// K = 0 disables the observer: no DMI traffic, snapshot fields stay zero.
1006	// This is the wire-format K=0 contract from F13: a zero mcycle_at_measure_start
1007	// downstream means "warmup not enabled / not reached".
1008	//
1009	// Capture sequence on the K-th retire: halt the hart via DMCONTROL,
1010	// abstract-read mcycle and minstret, then issue resumereq so the workload
1011	// continues. Each halt-read-resume cycle is one-shot per run; the flag
1012	// `reached_` guards against re-capture.
1013	
1014	#pragma once
1015	
1016	#include "hybrid/abstract_command.hpp"
1017	#include "hybrid/dmi_poll.hpp"
1018	#include "hybrid/resume_driver.hpp"
1019	
1020	#include <cstdint>
