1022	namespace hybrid
1023	{
1024	
1025	class MeasureStartSnapshot
1026	{
1027	public:
1028	  using RD = ResumeDriver;
1029	
1030	  MeasureStartSnapshot(uint64_t k, DmiBus& bus)
1031	      : k_{k}, bus_{&bus}
1032	  {}
1033	
1034	  // Move construction transfers state and bus pointer.
1035	  MeasureStartSnapshot(MeasureStartSnapshot&&) noexcept            = default;
1036	  MeasureStartSnapshot& operator=(MeasureStartSnapshot&&) noexcept = default;
1037	
1038	  void observe_commit()
1039	  {
1040	    if (k_ == 0 || reached_) return;
1041	    ++retired_;
1042	    if (retired_ != k_) return;
1043	    capture();
1044	    reached_ = true;
1045	  }
1046	
1047	  auto snapshot_reached() const -> bool { return reached_; }
1048	  auto mcycle_at_measure_start() const -> uint64_t { return mcycle_; }
1049	  auto minstret_at_measure_start() const -> uint64_t { return minstret_; }
1050	  auto target() const -> uint64_t { return k_; }
1051	
1052	private:
1053	  void capture()
1054	  {
1055	    // Halt the hart so abstract-command CSR reads are accepted.
1056	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive);
1057	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
1058	    poll_until_set(*bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
1059	                   "MeasureStartSnapshot halt");
1060	
1061	    mcycle_   = read_csr_64(RD::kCsrMcycle);
1062	    minstret_ = read_csr_64(RD::kCsrMinstret);
1063	
1064	    // Resume so the warmup window continues into the measured region.
1065	    // The hart re-acks via DmstatusAllresumeack, but we do not block here:
1066	    // the simulator's run loop drives the next sc_start, which lets the
1067	    // hart's running state propagate naturally.
1068	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
1069	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive);  // clear resumereq
1070	  }
1071	
1072	  auto read_csr_64(uint16_t csr) -> uint64_t
1073	  {
1074	    bus_->write(RD::kCommand,
1075	                access_register_command(regno_csr(csr), AarSize::Bits64,
1076	                                        /*write=*/false));
1077	    poll_until_clear(*bus_, RD::kAbstractcs, RD::kAbstractcsBusy,
1078	                     "MeasureStartSnapshot read_csr");
1079	    const auto status = bus_->read(RD::kAbstractcs);
1080	    if ((status & RD::kAbstractcsCmderrMask) != 0u) {
1081	      // Sticky error path mirrors StateDrain: clear and report zero.
1082	      bus_->write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
1083	      return 0u;
1084	    }
1085	    const uint64_t lo = bus_->read(RD::kData0);
1086	    const uint64_t hi = bus_->read(RD::kData1);
1087	    return lo | (hi << 32);
1088	  }
1089	
1090	  uint64_t k_;
1091	  DmiBus*  bus_;
1092	  uint64_t retired_ = 0;
1093	  bool     reached_ = false;
1094	  uint64_t mcycle_  = 0;
1095	  uint64_t minstret_ = 0;
1096	};
