112	  auto read_64bit_register(uint16_t regno) -> uint64_t
113	  {
114	    bus_.write(RD::kCommand, access_register_command(regno, AarSize::Bits64,
115	                                                     /*write=*/false));
116	    poll_until_clear(bus_, RD::kAbstractcs, RD::kAbstractcsBusy,
117	                     "StateDrain read_register");
118	    // If the hardware DM does not implement Abstract access for this
119	    // register, cmderr is set sticky and DATA0/DATA1 hold stale bytes.
120	    // Clear the error and report 0 for that field so the next read can
121	    // proceed - a missing CSR mirrors as zero rather than corrupting the
122	    // adjacent slot.
123	    const auto status = bus_.read(RD::kAbstractcs);
124	    if ((status & RD::kAbstractcsCmderrMask) != 0u) {
125	      bus_.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
126	      return 0u;
127	    }
128	    const uint64_t lo = bus_.read(RD::kData0);
129	    const uint64_t hi = bus_.read(RD::kData1);
130	    return lo | (hi << 32);
131	  }
